// WatchbillReplyAddSections contributes this kind's tagged sections to the OPEN
// entity on dml — the BuildEntities body without the entity frame.
// The caller owns BeginEntity / plain setters / CommitEntity.
func WatchbillReplyAddSections[
	BoolAttr WatchbillReplyBoolAttrI,
	BoolSec WatchbillReplyBoolSecI[BoolAttr, Ent],
	TextArrayAttr WatchbillReplyTextArrayAttrI,
	TextArraySec WatchbillReplyTextArraySecI[TextArrayAttr, Ent],
	StringArrayAttr WatchbillReplyStringArrayAttrI,
	StringArraySec WatchbillReplyStringArraySecI[StringArrayAttr, Ent],
	SymbolArrayAttr WatchbillReplySymbolArrayAttrI,
	SymbolArraySec WatchbillReplySymbolArraySecI[SymbolArrayAttr, Ent],
	U64ArrayAttr WatchbillReplyU64ArrayAttrI,
	U64ArraySec WatchbillReplyU64ArraySecI[U64ArrayAttr, Ent],
	I64ArrayAttr WatchbillReplyI64ArrayAttrI,
	I64ArraySec WatchbillReplyI64ArraySecI[I64ArrayAttr, Ent],
	Ent any,
	DML WatchbillReplyEntityI[
		BoolAttr, BoolSec,
		TextArrayAttr, TextArraySec,
		StringArrayAttr, StringArraySec,
		SymbolArrayAttr, SymbolArraySec,
		U64ArrayAttr, U64ArraySec,
		I64ArrayAttr, I64ArraySec,
		Ent,
	],
](dml DML, row WatchbillReply) (err error) {
	// --- bool. ---
	boolSec := dml.GetSectionBool()
	err = WatchbillReplyEmitSectionBool(boolSec, row)
	if err != nil {
		return
	}
	boolSec.EndSection()
	// --- textArray. ---
	textArraySec := dml.GetSectionTextArray()
	err = WatchbillReplyEmitSectionTextArray(textArraySec, row)
	if err != nil {
		return
	}
	textArraySec.EndSection()
	// --- stringArray. ---
	stringArraySec := dml.GetSectionStringArray()
	err = WatchbillReplyEmitSectionStringArray(stringArraySec, row)
	if err != nil {
		return
	}
	stringArraySec.EndSection()
	// --- symbolArray. ---
	symbolArraySec := dml.GetSectionSymbolArray()
	err = WatchbillReplyEmitSectionSymbolArray(symbolArraySec, row)
	if err != nil {
		return
	}
	symbolArraySec.EndSection()
	// --- u64Array. ---
	u64ArraySec := dml.GetSectionU64Array()
	err = WatchbillReplyEmitSectionU64Array(u64ArraySec, row)
	if err != nil {
		return
	}
	u64ArraySec.EndSection()
	// --- i64Array. ---
	i64ArraySec := dml.GetSectionI64Array()
	err = WatchbillReplyEmitSectionI64Array(i64ArraySec, row)
	if err != nil {
		return
	}
	i64ArraySec.EndSection()
	return
}

