// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around WatchbillReplyBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// WatchbillReplyEntityI.
func (c *WatchbillReplyColumns) Marshal(w io.Writer) (err error) {
	ent := watchbillReplyPool.Get().(*cbdml.InEntityFacts)
	defer watchbillReplyPool.Put(ent)
	ent.SetActiveSections(WatchbillReplyActiveSections)
	ent.Builder().SetActiveFields(WatchbillReplyActiveFields())
	err = WatchbillReplyBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("watchbillreply: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("watchbillreply: marshal write: %w", err)
	}
	return
}

